#!/usr/bin/env python3
"""Offline checks of the existing source/build pins; generated bytes checked by Gradle."""
import hashlib
import importlib.util
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]

def require(ok, message):
    if not ok:
        raise ValueError(message)

def checked(name, sha):
    p = Path(name)
    require(not p.is_absolute() and '..' not in p.parts, f'Unsafe manifest path: {name}')
    require(bool(re.fullmatch('[0-9a-f]{64}', sha)), f'Invalid SHA256: {name}')
    require(hashlib.sha256((ROOT / p).read_bytes()).hexdigest() == sha, f'Checksum mismatch: {name}')

def main():
    sources = json.loads((ROOT / 'sources.lock.json').read_text())
    require(set(sources) == {'eurobuddha/minima-core-android', 'themightydanik/minima-core',
                            'spartacusrex-minima/minima-core', 'themightydanik/trackium'}, 'Source pin set changed')
    for repo, data in sources.items():
        require(bool(re.fullmatch('[0-9a-f]{40}', data['commit'])), f'Invalid commit: {repo}')
    checked('app/libs/minima.jar', sources['eurobuddha/minima-core-android']['minima_jar_sha256'])
    imported = json.loads((ROOT / 'UPSTREAM_NOTICES/import-hashes.json').read_text())
    for name in ('LICENSE', 'gradlew', 'gradlew.bat', 'gradle/wrapper/gradle-wrapper.jar',
                 'gradle/wrapper/gradle-wrapper.properties', 'scripts/keets-dependencies.lock.json'):
        checked(name, imported[name])
    wrapper = (ROOT / 'gradle/wrapper/gradle-wrapper.properties').read_text()
    require(bool(re.search(r'^distributionSha256Sum=[0-9a-f]{64}$', wrapper, re.M)), 'Wrapper download SHA missing')
    require('https\\://services.gradle.org/distributions/gradle-8.11.1-bin.zip' in wrapper, 'Wrapper URL changed')
    pins = json.loads((ROOT / 'scripts/keets-dependencies.lock.json').read_text())
    checked('scripts/keets-tools/package.json', pins['tools']['package_sha256'])
    checked('scripts/keets-tools/package-lock.json', pins['tools']['lock_sha256'])
    for name, data in json.loads((ROOT / 'UPSTREAM_NOTICES/engine-test-hashes.json').read_text()).items():
        checked(name, data['sha256'])
    for pin in [pins['source'], pins['runtime'], *pins['node']['platforms'].values()]:
        require(pin['url'].startswith('https://') and bool(re.fullmatch('[0-9a-f]{64}', pin['sha256'])), 'Unpinned download')
    for name, sha in pins['outputs'].items():
        require(not Path(name).is_absolute() and '..' not in Path(name).parts and bool(re.fullmatch('[0-9a-f]{64}', sha)), 'Invalid generated output pin')
    spec = importlib.util.spec_from_file_location('prepare', ROOT / 'scripts/prepare-keets.py')
    prepare = importlib.util.module_from_spec(spec); spec.loader.exec_module(prepare)
    prepare.validate_npm_lock(ROOT / 'scripts/keets-tools/package-lock.json')
    print('Source commits, engine, original licence, wrapper, tools, downloads and regression provenance: PASS')

if __name__ == '__main__':
    main()
